class MooncakeNVLinkAllocator:
    _instances: Dict[torch.device, CUDAPluggableAllocator] = {}
    _lock: Final = threading.Lock()

    @classmethod
    def _get_so_path(cls) -> str:
        """Dynamically locate hook.so in the mooncake package installation"""
